import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse('{"title":"Run your trading office","description":"Run day-to-day Trading Office work through the Control Center and add fund-team administration when you need it.","frontmatter":{"title":"Run your trading office","description":"Run day-to-day Trading Office work through the Control Center and add fund-team administration when you need it.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/operations"}]]},"headers":[],"relativePath":"trading-office/operations.md","filePath":"trading-office/operations.md"}'),n={name:"trading-office/operations.md"};function r(s,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="run-your-trading-office" tabindex="-1">Run your trading office <a class="header-anchor" href="#run-your-trading-office" aria-label="Permalink to &quot;Run your trading office&quot;">​</a></h1><p>Trading Office is organized around one selected trading book. The office lead coordinates employees and standing work, while the local Trading Office record preserves the book, mandates, workflow runs, research, and paper transactions. The current interface labels the office lead surface the <strong>CEO pane</strong>.</p><p>The everyday controls apply whether you are a solo trader, an emerging manager, or part of a fund team. Additional LP and capital-record features appear later on this page. For the strategy lifecycle, begin with <a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your First Strategy</a>.</p><h2 id="everyday-trading-office-operations" tabindex="-1">Everyday Trading Office operations <a class="header-anchor" href="#everyday-trading-office-operations" aria-label="Permalink to &quot;Everyday Trading Office operations&quot;">​</a></h2><h3 id="start-in-the-control-center" tabindex="-1">Start in the Control Center <a class="header-anchor" href="#start-in-the-control-center" aria-label="Permalink to &quot;Start in the Control Center&quot;">​</a></h3><p>Open the selected book&#39;s Control Center from the office lead—the current <strong>CEO pane</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:control</span></span></code></pre></div><p>It brings the operating state of the book into one view:</p><ul><li>the selected book and session mode;</li><li>active employees and recommended-role coverage;</li><li>active mandates and configured workflows;</li><li>due, running, waiting, and failed workflow runs;</li><li>unread escalations; and</li><li>recent activity.</li></ul><p>From here you can complete the recommended setup, manage the team, edit mandates, manage workflows, inspect activity, or pause scheduled employee workflows for the book.</p><h4 id="pause-scheduled-work-safely" tabindex="-1">Pause scheduled work safely <a class="header-anchor" href="#pause-scheduled-work-safely" aria-label="Permalink to &quot;Pause scheduled work safely&quot;">​</a></h4><p><strong>Pause all scheduled workflows</strong> invalidates pending and waiting employee runs. It does not close paper positions, remove watches, or stop the deterministic position monitor. A run that is already executing is not cancelled and may create its next scheduled run when it finishes; inspect the workflow again after the current run completes.</p><p>Use <a href="/trading-sandbox-website-preview/wiki/trading-office/watches#inspect-watches-in-cron-monitor">Cron Monitor</a> for scheduled watches and <a href="/trading-sandbox-website-preview/wiki/trading-office/paper-operations#monitor-in-market-terminal">Market Terminal</a> for open paper positions.</p><h4 id="use-autonomous-·-paper-trading-for-standing-work" tabindex="-1">Use Autonomous · Paper trading for standing work <a class="header-anchor" href="#use-autonomous-·-paper-trading-for-standing-work" aria-label="Permalink to &quot;Use Autonomous · Paper trading for standing work&quot;">​</a></h4><p>In Autonomous · Paper trading, due employee workflows can research, report, and prepare or book mandate-constrained Office paper trades. Review the selected mode, mandates, workflow cadence, and escalation rules together before allowing standing work to continue.</p><h3 id="direct-the-office-from-the-lead-pane" tabindex="-1">Direct the office from the lead pane <a class="header-anchor" href="#direct-the-office-from-the-lead-pane" aria-label="Permalink to &quot;Direct the office from the lead pane&quot;">​</a></h3><p>The lead pane is the coordination desk. Ask it in ordinary language to delegate a bounded task to an <strong>Investor</strong> or <strong>Trader</strong>, optionally naming the employee.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ask the Investor to challenge the assumptions behind the gap-fill idea and report the strongest falsification case.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ask the Trader to scan the approved universe, prepare one paper setup within the stored mandate, and report any blocked risk checks.</span></span></code></pre></div><p>The task is delivered through the office mailbox to the employee pane. The employee works with its own identity and book scope, then sends a result or status report back to the CEO. Active employee panes are started automatically when the CEO enters the office.</p><p>A useful delegation states:</p><ol><li>the decision or output needed;</li><li>the universe, evidence, or book context to use;</li><li>constraints that must not be relaxed; and</li><li>what should be escalated instead of acted on.</li></ol><p>Mailbox reports are coordination artifacts, not a substitute for durable state. Confirm positions and fills in Market Terminal, workflow state in Control Center, and strategy evidence in the Strategy Library.</p><h3 id="choose-and-administer-trading-books" tabindex="-1">Choose and administer trading books <a class="header-anchor" href="#choose-and-administer-trading-books" aria-label="Permalink to &quot;Choose and administer trading books&quot;">​</a></h3><p>Use the CEO book picker to choose or create the active book:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:books</span></span></code></pre></div><p>Each book carries its own market context, paper cash, employees, clients, positions, records, mandates, and workflows. India books use INR and the India market context; US books use USD and the US market context. Switching books changes the scope of the office panes that are launched.</p><p>Use the setup cards for launch readiness:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:onboard</span></span></code></pre></div><p>Use deterministic administration to edit the selected book, manage employees, review mandates and workflows, or manage investor records:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:admin</span></span></code></pre></div><p>You can also ask the active Trading Office employee to show book facts such as:</p><ul><li>paper cash, units outstanding, and NAV per unit;</li><li>realized P&amp;L by instrument and in total;</li><li>the account ledger;</li><li>derived equity, option, and futures positions; and</li><li>fund-client or LP rows.</li></ul><p>For current marks and unrealized P&amp;L, use <code>/terminal</code> or ask for the live market-terminal view. When a quote is unavailable, the position should remain visible with a quote error rather than an invented mark.</p><h3 id="use-the-advanced-read-only-dashboard" tabindex="-1">Use the advanced read-only dashboard <a class="header-anchor" href="#use-the-advanced-read-only-dashboard" aria-label="Permalink to &quot;Use the advanced read-only dashboard&quot;">​</a></h3><p>The local Trading Office service serves an advanced browser view at <a href="http://127.0.0.1:8787/ui/" target="_blank" rel="noreferrer">http://127.0.0.1:8787/ui/</a> when the service is running.</p><p>Its current <strong>Hedge Fund</strong> area provides read-only views for:</p><ul><li>the audit summary and service health;</li><li>the trading book, cash, units, NAV, realized P&amp;L, and ledger;</li><li>positions and equity, option, and futures transactions;</li><li>records, clients, and employees; and</li><li>mandates, workflow exceptions, blocked risk decisions, unread mailbox items, and kill-switch state.</li></ul><p>The dashboard does not mutate Office state. Use tradecli administration for books, employees, and LP creation; Control Center for mandates and workflows; and the Strategy Library for versions, deployments, journals, and reviews.</p><h3 id="a-practical-operating-rhythm" tabindex="-1">A practical operating rhythm <a class="header-anchor" href="#a-practical-operating-rhythm" aria-label="Permalink to &quot;A practical operating rhythm&quot;">​</a></h3><p>At the start of a session:</p><ol><li>Confirm the selected book and mode in Control Center.</li><li>Read escalations, failed runs, and mandate coverage.</li><li>Check Market Terminal for open paper risk.</li></ol><p>During the session, delegate bounded research, use watches for repeated observations, and keep standing employee work inside explicit mandates. Before leaving, inspect recent activity, pause work that should not continue, and preserve strategy decisions through the journal and review flow.</p><h2 id="additional-operations-for-fund-teams" tabindex="-1">Additional operations for fund teams <a class="header-anchor" href="#additional-operations-for-fund-teams" aria-label="Permalink to &quot;Additional operations for fund teams&quot;">​</a></h2><p>These features extend the same Trading Office model for managers who track outside capital or report across a team.</p><h3 id="add-investors-and-lps" tabindex="-1">Add investors and LPs <a class="header-anchor" href="#add-investors-and-lps" aria-label="Permalink to &quot;Add investors and LPs&quot;">​</a></h3><p>Open <code>/hedgefund:admin</code>, choose <strong>Manage investors / LPs</strong>, then <strong>Add investor / LP</strong>. The current form records:</p><ul><li>a name;</li><li>capital contributed;</li><li>optional units; and</li><li>an optional high-water mark.</li></ul><p>The record becomes part of fund summaries and the read-only Office dashboard alongside units, NAV, high-water marks, P&amp;L, and ledger state.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/setup">Set up your office</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation tools</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/paper-operations">Paper trade and monitor</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/review">Review and improve</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/concepts">Concepts and terminology</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/commands">Commands and shortcuts</a></li></ul>',51)])])}const f=a(n,[["render",r]]);export{u as __pageData,f as default};
